POLICIES = {
"KB-01": {"title":"Password Reset","text":"Employees can reset their own password via the self-service portal at any time. If locked out after 5 failed attempts, contact IT to unlock the account manually. No approval required."},
"KB-02": {"title":"VPN Access","text":"VPN access is granted automatically to all full-time employees. Contractors require manager approval submitted via the access request form. VPN credentials expire every 90 days and must be renewed by the employee."},
"KB-03": {"title":"Laptop Replacement","text":"Laptops are eligible for replacement after 3 years of service, or earlier in case of verified hardware failure. Requests must be raised at least 2 weeks in advance of intended replacement."},
"KB-04": {"title":"Software Installation Requests","text":"Standard software in the approved catalog can be self-installed. Non-catalog software requires IT Security review, which takes 3–5 business days."},
"KB-05": {"title":"Printer Troubleshooting","text":"First check the printer queue and restart the print spooler. If the issue persists, log a ticket with the printer asset tag."},
"KB-06": {"title":"Email Mailbox Quota","text":"Default mailbox quota is 25GB. Employees nearing quota should archive old mail. Increases beyond 25GB require manager approval and are capped at 50GB."},
"KB-07": {"title":"Guest Wi-Fi Access","text":"Guest Wi-Fi credentials are valid for 24 hours and can be generated by any employee from the front-desk kiosk. No IT ticket required."},
"KB-08": {"title":"Expense Software Access","text":"Expense tool access is granted by Finance, not IT. IT can assist with login or technical issues once an account already exists."},
"KB-09": {"title":"Security Incident Reporting","text":"Suspected phishing, malware, or unauthorized access must be reported to security@veridian-corp.example immediately and must not be forwarded to other employees."},
"KB-10": {"title":"Work-From-Home Equipment","text":"Employees working remotely more than 3 days/week are eligible for a one-time home office allowance. Manager sign-off and Finance processing are required; IT handles shipping after approval."},
"ASSET": {"title":"Asset Management Policy (Q2 2026)","text":"All company hardware follows a standard 4-year refresh cycle. Early replacement requires Finance sign-off in addition to IT approval."}
}
